const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/titletruncate";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  const p = path.join(dir, file);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
}
function vitest(args, cwd) {
  const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", ...args], {
    cwd: cwd || dir,
    encoding: "utf8",
    env: { ...process.env, NO_COLOR: "1", CI: "1" },
    timeout: 60000,
  });
  return { status: r.status, out: (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "") };
}

// chaiConfig.truncateThreshold: 0 used to disable truncation of test.each title values.
write("vitest.config.mjs", "export default { test: { chaiConfig: { truncateThreshold: 0 } } }\n");
write("each.test.mjs", [
  "import { test } from 'vitest'",
  "test.each([{ param: '0123456789'.repeat(5) }])('title $param', () => {})",
].join("\n") + "\n");
const r = vitest(["run", "--reporter=json", "--outputFile=report.json"]);
console.log(r.out);
const reportFile = path.join(dir, "report.json");
if (!fs.existsSync(reportFile)) {
  console.error("ERROR: vitest wrote no JSON report (exit " + r.status + ")");
  process.exit(2);
}
const report = JSON.parse(fs.readFileSync(reportFile, "utf8"));
const titles = [];
for (const file of report.testResults || []) {
  for (const a of file.assertionResults || []) titles.push(a.title);
}
console.log("titles: " + JSON.stringify(titles));
if (titles.length !== 1 || report.numPassedTests !== 1 || !titles[0].startsWith("title '0123456789")) {
  console.error("ERROR: unexpected report (titles " + JSON.stringify(titles) + ", exit " + r.status + ")");
  process.exit(2);
}
const full = "0123456789".repeat(5);
const title = titles[0];
if (!title.includes(full) && title.includes("\u2026")) {
  console.log("PASS: test.each title value is truncated despite chaiConfig.truncateThreshold 0: " + title);
  process.exit(0);
}
if (title.includes(full)) {
  console.error("FAIL: chaiConfig.truncateThreshold 0 disabled truncation of the test.each title value");
  process.exit(1);
}
console.error("ERROR: unexpected title " + JSON.stringify(title));
process.exit(2);

